#[inline(never)]
pub fn exact_input_tokens(quote:u64,reserve_out:u64,reserve_in:u64)->Result<u64>{
    let effective=quote.checked_sub(1).ok_or(PumpError::Overflow)?;
    let amount=crate::constant_product::output(effective as u128,reserve_in as u128,reserve_out as u128)?;
    u64::try_from(amount).map_err(|_|error!(PumpError::Truncation))
}

use anchor_lang::prelude::*;
use crate::PumpError;

#[inline(never)]
pub fn output(amount_in:u128,reserve_in:u128,reserve_out:u128)->Result<u128> {






    let numerator=amount_in.checked_mul(reserve_out)
        .ok_or_else(||error!(PumpError::Overflow))?;


    let denominator=reserve_in.checked_add(amount_in)
        .ok_or_else(||error!(PumpError::Overflow))?;
    numerator.checked_div(denominator)
        .ok_or_else(||error!(PumpError::DivisionByZero))
}

#[inline(never)]
pub fn tokens_for_quote(curve:&crate::trade_types::BondingCurve,quote:u64)->Result<u128>{
    let effective=quote.checked_sub(1).ok_or(PumpError::Overflow)?;
    output(effective as u128,curve.virtual_quote_reserves as u128,curve.virtual_token_reserves as u128)
}
